(()=>{const s=localStorage,p=Storage.prototype,rows=[],keys=()=>Array.from({length:s.length},(_,i)=>p.key.call(s,i)),snap=operation=>rows.push({operation,keys:keys(),own:Object.keys(s),raw:Reflect.ownKeys(s).map(String)}),names=Array.from({length:90},(_,i)=>i%3===0?'key:'+i+':'+('🐼xyé').repeat(i%19):i%3===1?'x'.repeat(i+1):String(10000-i));s.clear();for(let i=0;i<names.length;i++){s.setItem(names[i],String(i));if(i%7===0)snap('insert:'+i)}for(let i=1;i<names.length;i+=3)s.removeItem(names[i]);snap('delete');for(let i=names.length-1;i>=0;i-=2)s.setItem(names[i],'replace');snap('reinsert');for(let i=0;i<40;i++)s.setItem('fresh:'+i,'value');snap('grow');s.clear();for(const key of['a','b','c','d','e','f','g','h'])s.setItem(key,key);snap('clear-refill');return rows;})()
